<?php
require_once __DIR__ . '/../includes/auth.php'; require_role(['student']); require __DIR__ . '/../config/database.php';
$pageTitle='Grades and Progress'; $q=$pdo->prepare("SELECT a.title,a.activity_type,s.subject_name,sub.score,sub.feedback,sub.status,sub.submitted_at FROM submissions sub JOIN activities a ON a.id=sub.activity_id JOIN subjects s ON s.id=a.subject_id WHERE sub.student_id=? ORDER BY sub.submitted_at DESC"); $q->execute([$_SESSION['user_id']]);$rows=$q->fetchAll();require __DIR__ . '/../includes/header.php'; ?>
<section class="panel"><div class="panel-head"><h3>My results</h3></div><?php if(!$rows): ?><p class="empty">Your grades and feedback will appear here after you submit activities.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Activity</th><th>Subject</th><th>Type</th><th>Score</th><th>Status</th><th>Teacher feedback</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['subject_name']) ?></td><td><?= e(ucfirst($r['activity_type'])) ?></td><td><?= $r['score']===null?'—':e($r['score']) ?></td><td><?= e(ucfirst($r['status'])) ?></td><td><?= e($r['feedback'] ?: 'No feedback yet') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<?php require __DIR__ . '/../includes/footer.php'; ?>
